PAGE='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PanelPress Anime Library</title><style>\n:root{--line:#2a3143;--text:#f4f6fb;--muted:#9ca7bc;--accent:#a78bfa;--accent2:#6d5ce8}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top left,#20203b 0,#0b0d14 48%);color:var(--text);font:15px/1.5 system-ui,Segoe UI,Arial,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:0;border-radius:10px;padding:10px 14px;background:var(--accent2);color:white;font-weight:650}button:hover{filter:brightness(1.12)}button.secondary{background:#282f40;border:1px solid #3a4358}button:disabled{opacity:.45;cursor:wait}.shell{max-width:1450px;margin:auto;padding:28px}.top{display:flex;gap:18px;align-items:center;justify-content:space-between;flex-wrap:wrap;margin-bottom:24px}.brand{display:flex;gap:13px;align-items:center}.logo{width:48px;height:48px;border-radius:15px;display:grid;place-items:center;background:linear-gradient(135deg,#b69aff,#6452df);font-size:25px}.brand h1{margin:0;font-size:25px}.brand p{margin:2px 0 0;color:var(--muted)}.stats{display:flex;gap:10px;flex-wrap:wrap}.pill{padding:8px 12px;background:#171b29;border:1px solid var(--line);border-radius:12px;color:var(--muted)}.pill b{color:white}.layout{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(320px,.85fr);gap:20px;align-items:start}.card{background:#121622ed;border:1px solid var(--line);border-radius:18px;overflow:hidden;box-shadow:0 16px 50px #0002}.cardhead{padding:18px 20px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:10px;align-items:center}.cardhead h2{font-size:17px;margin:0}.cardbody{padding:18px 20px}.filters{display:grid;grid-template-columns:1fr 170px 130px;gap:10px;margin-bottom:14px}input,select{min-width:0;width:100%;background:#0d111b;color:var(--text);border:1px solid #30384c;border-radius:10px;padding:11px 12px;outline:none}.library{max-height:65vh;overflow:auto}.group-title{font-size:13px;text-transform:uppercase;letter-spacing:.09em;color:#b9a9ff;font-weight:750;margin:16px 0 8px}.ep{display:flex;gap:10px;align-items:center;padding:11px 10px;border-radius:12px;border:1px solid transparent}.ep:hover{background:#1b2130}.ep.active{background:#25213c;border-color:#6453a7}.epinfo{flex:1;min-width:0}.epname{font-weight:650;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.epmeta{font-size:12px;color:var(--muted);margin-top:2px}.epbuttons{display:flex;gap:6px}.epbuttons button{padding:7px 10px;font-size:12px}.playerbox{background:#080a0f;aspect-ratio:16/9;display:grid;place-items:center}.playerbox video{width:100%;height:100%;max-height:420px;background:#000}.empty{text-align:center;color:var(--muted);padding:35px}.now{font-weight:750;margin:0 0 4px}.sub{color:var(--muted);font-size:13px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:14px}.queue{margin-top:20px}.job{padding:12px 0;border-bottom:1px solid #252c3b}.jobtop{display:flex;justify-content:space-between;gap:8px}.status{font-size:12px;color:var(--muted)}.bar{height:6px;background:#282e3d;border-radius:10px;overflow:hidden;margin-top:8px}.bar span{height:100%;display:block;background:linear-gradient(90deg,#8c73ff,#61d7b0);width:0%}.error{color:#ff7c8d}.foot{margin-top:22px;color:#778197;font-size:12px}.hidden{display:none}@media(max-width:950px){.layout{grid-template-columns:1fr}.library{max-height:none}}@media(max-width:600px){.shell{padding:14px}.filters{grid-template-columns:1fr}.epbuttons{flex-direction:column}.brand h1{font-size:21px}}\n</style></head><body><main class="shell"><header class="top"><div class="brand"><div class="logo">▶</div><div><h1>PanelPress <span style="color:#b9a9ff">Anime Library</span></h1><p>Browse · stream · download</p></div></div><div class="stats"><div class="pill"><b id="count">—</b> URLs</div><div class="pill"><b id="seriesCount">—</b> series</div><div class="pill">Source: <b>Archive.org</b></div></div></header><div class="layout"><section class="card"><div class="cardhead"><h2>📚 Library</h2><button class="secondary" onclick="queueVisible()">Download filtered</button></div><div class="cardbody"><div class="filters"><input id="search" placeholder="Search anime or episode…"><select id="series"><option value="">All series</option></select><select id="season"><option value="">All seasons</option></select></div><div id="library" class="library"></div></div></section><section><div class="card"><div class="cardhead"><h2>🎬 Player</h2><span class="sub" id="playStatus">Choose an episode</span></div><div class="playerbox"><video id="player" controls playsinline preload="metadata"></video><div id="playerEmpty" class="empty">Select an episode to play it here.</div></div><div class="cardbody"><p class="now" id="nowTitle">Nothing playing</p><div class="sub" id="nowMeta">Choose an episode from the library.</div><div class="actions"><button class="secondary" onclick="step(-1)">← Previous</button><button onclick="step(1)">Next →</button><button class="secondary" id="downloadCurrent" disabled>Download episode</button></div><p class="sub">If the browser cannot play a source, try downloading it or opening the source directly.</p><div class="actions"><button class="secondary" id="openSource" disabled>Open source ↗</button></div></div></div><div class="card queue"><div class="cardhead"><h2>⬇ Download queue</h2><button class="secondary" onclick="refreshJobs()">Refresh</button></div><div class="cardbody" id="jobs"><div class="sub">No downloads queued yet.</div></div></div></section></div><div class="foot">Local Flask app · Files are saved to the downloads/ folder. Only download media you have permission to access.</div></main><script>\nlet items=[],selected=null,visible=[];const $=id=>document.getElementById(id);\nasync function init(){items=await(await fetch(\'/api/catalog\')).json();$(\'count\').textContent=items.length;$(\'seriesCount\').textContent=new Set(items.map(x=>x.series)).size;[...new Set(items.map(x=>x.series))].sort().forEach(n=>{let o=document.createElement(\'option\');o.value=n;o.textContent=n;$(\'series\').append(o)});$(\'search\').oninput=render;$(\'series\').onchange=()=>{updateSeasons();render()};$(\'season\').onchange=render;updateSeasons();render();refreshJobs();setInterval(refreshJobs,2500)}\nfunction updateSeasons(){let old=$(\'season\').value;$(\'season\').innerHTML=\'<option value="">All seasons</option>\';items.filter(x=>!$(\'series\').value||x.series===$(\'series\').value).map(x=>x.season).filter((v,i,a)=>a.indexOf(v)===i).sort((a,b)=>a-b).forEach(n=>{let o=document.createElement(\'option\');o.value=n;o.textContent=\'Season \'+n;$(\'season\').append(o)});if([...$(\'season\').options].some(o=>o.value===old))$(\'season\').value=old}\nfunction render(){let q=$(\'search\').value.toLowerCase(),s=$(\'series\').value,se=$(\'season\').value;visible=items.filter(x=>(!s||x.series===s)&&(!se||String(x.season)===se)&&(!q||(x.series+\' \'+x.title+\' \'+x.filename).toLowerCase().includes(q)));let root=$(\'library\');root.innerHTML=\'\';if(!visible.length){root.innerHTML=\'<div class="empty">No matching episodes.</div>\';return}let last=\'\';for(let item of visible){let group=item.series+\'|\'+item.season;if(group!==last){let g=document.createElement(\'div\');g.className=\'group-title\';g.textContent=item.series+(item.series===\'Death Note\'||item.series===\'Naruto Shippuden\'?\'\':\' · Season \'+item.season);root.append(g);last=group}let row=document.createElement(\'div\');row.className=\'ep\'+(selected&&selected.url===item.url?\' active\':\'\');let inf=document.createElement(\'div\');inf.className=\'epinfo\';let name=document.createElement(\'div\');name.className=\'epname\';name.textContent=item.title;let meta=document.createElement(\'div\');meta.className=\'epmeta\';meta.textContent=item.series+\' · \'+item.filename;inf.append(name,meta);let btns=document.createElement(\'div\');btns.className=\'epbuttons\';let play=document.createElement(\'button\');play.textContent=\'Play\';play.onclick=()=>playItem(item);let dl=document.createElement(\'button\');dl.textContent=\'↓\';dl.title=\'Download\';dl.className=\'secondary\';dl.onclick=()=>enqueue([item]);btns.append(play,dl);row.append(inf,btns);root.append(row)}}\nfunction playItem(x){selected=x;$(\'player\').src=x.url;$(\'player\').load();$(\'playerEmpty\').classList.add(\'hidden\');$(\'nowTitle\').textContent=x.series+\' — \'+x.title;$(\'nowMeta\').textContent=\'Season \'+x.season+\' · \'+x.filename;$(\'playStatus\').textContent=\'Source selected\';$(\'downloadCurrent\').disabled=false;$(\'openSource\').disabled=false;$(\'downloadCurrent\').onclick=()=>enqueue([x]);$(\'openSource\').onclick=()=>window.open(x.url,\'_blank\',\'noopener\');render();$(\'player\').play().catch(()=>{$(\'playStatus\').textContent=\'Press play or open source\'})}\nfunction step(d){let arr=visible.length?visible:items;if(!selected){if(arr.length)playItem(arr[0]);return}let i=arr.findIndex(x=>x.url===selected.url);if(i<0)i=items.findIndex(x=>x.url===selected.url);if(arr[i+d])playItem(arr[i+d])}\nasync function enqueue(arr){if(!arr.length)return;let r=await fetch(\'/api/downloads\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({items:arr.map(x=>x.url)})});let d=await r.json();if(!r.ok)alert(d.error||\'Could not queue downloads\');refreshJobs()}function queueVisible(){enqueue(visible)}\nasync function refreshJobs(){try{let list=await(await fetch(\'/api/downloads\')).json(),root=$(\'jobs\');root.innerHTML=\'\';if(!list.length){root.innerHTML=\'<div class="sub">No downloads queued yet.</div>\';return}for(let j of list.slice().reverse()){let el=document.createElement(\'div\');el.className=\'job\';let top=document.createElement(\'div\');top.className=\'jobtop\';let title=document.createElement(\'b\');title.textContent=j.name;let status=document.createElement(\'span\');status.className=\'status \'+(j.status===\'error\'?\'error\':\'\');status.textContent=j.status+(j.status===\'downloading\'?\' · \'+j.percent+\'%\':\'\');top.append(title,status);let bar=document.createElement(\'div\');bar.className=\'bar\';let fill=document.createElement(\'span\');fill.style.width=j.percent+\'%\';bar.append(fill);let detail=document.createElement(\'div\');detail.className=\'status\';detail.textContent=j.message||j.bytes||\'\';el.append(top,bar,detail);root.append(el)}}catch(e){}}init().catch(e=>{$(\'library\').textContent=\'Could not load catalog: \'+e});\n</script></body></html>'
app=Flask(__name__)
jobs={}
lock=threading.Lock()

@app.get('/')
def home(): return render_template_string(PAGE)
@app.get('/api/catalog')
def catalog(): return jsonify(CATALOG)
@app.get('/api/downloads')
def list_downloads():
 with lock: return jsonify(list(jobs.values()))

def safe_name(item):
 name=unquote(item.get('filename') or 'video.mp4')
 name=re.sub(r'[<>:"/\\|?*\x00-\x1f]','_',name).strip(' .')
 return name[:180] or 'video.mp4'

def worker(jid,item):
 job=jobs[jid]; dest=DOWNLOADS/safe_name(item)
 if dest.exists(): dest=DOWNLOADS/f"{dest.stem}_{jid[:6]}{dest.suffix}"
 tmp=dest.with_suffix(dest.suffix+'.part')
 try:
  with requests.get(item['url'],stream=True,timeout=(20,90),headers={'User-Agent':'PanelPressAnimeLibrary/1.0'}) as resp:
   resp.raise_for_status(); total=int(resp.headers.get('content-length') or 0); got=0
   with tmp.open('wb') as f:
    for chunk in resp.iter_content(chunk_size=262144):
     if not chunk: continue
     f.write(chunk); got+=len(chunk)
     with lock:
      job['bytes']=f'{got/1048576:.1f} MB'+(f' / {total/1048576:.1f} MB' if total else '')
      job['percent']=round(got*100/total) if total else 0
  tmp.replace(dest)
  with lock: job.update(status='complete',percent=100,message=f'Saved to downloads/{dest.name}',path=str(dest))
 except Exception as e:
  try: tmp.unlink(missing_ok=True)
  except Exception: pass
  with lock: job.update(status='error',message=str(e)[:240])

@app.post('/api/downloads')
def create_downloads():
 data=request.get_json(silent=True) or {}; requested=data.get('items',[])
 if not isinstance(requested,list) or not requested: return jsonify(error='No episodes selected.'),400
 by_url={x['url']:x for x in CATALOG}; added=[]
 for url in requested[:100]:
  item=by_url.get(url)
  if not item: continue
  jid=uuid.uuid4().hex[:12]; job={'id':jid,'name':item['series']+' — '+item['title'],'url':url,'status':'downloading','percent':0,'message':'Starting download','bytes':''}
  with lock: jobs[jid]=job
  threading.Thread(target=worker,args=(jid,item),daemon=True).start(); added.append(job)
 if not added: return jsonify(error='No recognized catalog URLs were submitted.'),400
 return jsonify(added),202

@app.get('/downloads/<path:name>')
def serve_download(name): return send_from_directory(DOWNLOADS,name,as_attachment=True)

if __name__=='__main__':
 print('PanelPress Anime Library: http://127.0.0.1:5000')
 app.run(host='127.0.0.1',port=int(os.environ.get('PORT','5000')),debug=False,threaded=True)
